import logging

from ...adapters.soap import SoapAdapter

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SwamSoapAdapter(SoapAdapter):

    def __init__(self, name, web_url, username, password):
        port = 10443
        client = 'SWAMClientWS'
        wsdl_url = f'https://{web_url}:{port}/{client}/{name}/{name}.wsdl'
        super().__init__(wsdl_url, username, password)

    @property
    def core_type_factory(self):
        """
        :rtype: zeep.client.Factory
        """
        return self.client.type_factory('http://nsn.com/oss/swam/core')
